import {supplierComparisonAction} from "@/lib/actions/supplier-comparisons";import {getSessionContext} from "@/lib/auth";
import {PageHeader} from "@/components/layout/page-header";import {NewSupplierOffer} from "@/components/modules/vendors/supplier-comparisons";
export default async function NewSupplierOfferPage({params}:{params:Promise<{id:string}>}){const {id}=await params,context=await getSessionContext(),result=await supplierComparisonAction({command:"request.load",request_id:id});return <div className="space-y-5"><PageHeader title="Record supplier offer" description={result.success&&result.kind==="comparison"?`${result.data.request.title}: ${result.data.request.quantity} ${result.data.request.unit}. ${result.data.request.specification}`:"Read the exact purchase requirement before recording its supplier offer."}/>{result.success?<NewSupplierOffer key={`${context.companyId}:${context.userId}:${context.role}:${id}`} requestId={id}/>:<p role="alert">{result.error}</p>}</div>;}
